mapper.update:
update face_recognition_events
track_id = #{trackId}, machine_id = #{machineId}, face_id = #{faceId}, confidence = #{confidence}, recognition_time = #{recognitionTime}, departure_time = #{departureTime}, detection_img = #{detectionImg},
where id = #{id}

UPDATE face_recognition_events_v1
SET identity_type = 'PERSON',
    face_id = #{personId}
WHERE identity_type = 'STRANGER'
  AND face_id = #{strangerId}
